
import { Link, useLocation } from 'react-router-dom';

interface GlobalHeaderProps {
  showBanner?: boolean;
  showSearch?: boolean;
}

const navItems = [
  { label: '総合トップ', to: '/' },
  { label: 'ショッピング', to: '/shop' },
  { label: '中古パーツ', to: '/used-parts' },
  { label: '車種選び', to: '/vehicle-select' },
  { label: 'ショップNAVI', to: '/shop-navi' },
  { label: 'メディア', to: '/media' },
  { label: 'サービス', to: '/services' },
  { label: 'コミュニティ', to: '/community' },
  { label: 'イベント', to: '/events' },
  { label: 'ご利用案内', to: '/guide' },
];

export default function GlobalHeader({ showBanner = true, showSearch = true }: GlobalHeaderProps) {
  const location = useLocation();
  const currentPath = location.pathname;

  const isActive = (to: string) => {
    if (to === '/') return currentPath === '/';
    return currentPath.startsWith(to);
  };

  return (
    <>
      {/* 最上部バナー帯 */}
      {showBanner && (
        <div className="flex">
          <div className="flex-1 bg-yellow-400 text-black py-2 px-4 text-center font-bold text-sm">
            5,500円以上で送料無料！
          </div>
          <div className="flex-1 bg-red-600 text-white py-2 px-4 text-center font-bold text-sm">
            数量限定シークレットセール開催中
          </div>
        </div>
      )}

      {/* グローバルナビゲーション */}
      <nav className="bg-gray-800 text-white">
        <div className="flex items-center justify-between px-6 py-3">
          <div className="flex gap-6 text-sm">
            {navItems.map((item) => (
              <Link
                key={item.to}
                to={item.to}
                className={`whitespace-nowrap cursor-pointer ${
                  isActive(item.to)
                    ? 'text-red-400 font-bold'
                    : 'hover:text-red-500'
                }`}
              >
                {item.label}
              </Link>
            ))}
          </div>
          <div className="flex gap-3 text-sm">
            <a href="#" className="hover:text-red-500 whitespace-nowrap cursor-pointer">ログイン</a>
            <span>/</span>
            <a href="#" className="hover:text-red-500 whitespace-nowrap cursor-pointer">新規会員登録</a>
          </div>
        </div>
      </nav>

      {/* ヘッダー */}
      {showSearch && (
        <header className="bg-white border-b border-gray-200 py-4 px-6">
          <div className="flex items-center justify-between max-w-[1400px] mx-auto">
            <Link to="/" className="flex flex-col cursor-pointer">
              <img
                src="https://static.readdy.ai/image/9cccc7697d198734aa718bd2a70664c9/288e4e86ff9691b6f96385bebb66c1e9.png"
                alt="AutoGarage"
                className="h-12 mb-1"
              />
              <p className="text-xs text-gray-500">自動車用品・パーツ・中古部品の総合通販サイト</p>
            </Link>
            <div className="flex-1 mx-8 max-w-2xl">
              <div className="flex">
                <input
                  type="text"
                  placeholder="商品名、品番、車種名で検索"
                  className="flex-1 border border-gray-300 px-4 py-3 text-sm focus:outline-none focus:border-red-500 cursor-text"
                />
                <button className="bg-red-600 text-white px-8 py-3 font-bold hover:bg-red-700 whitespace-nowrap cursor-pointer">
                  検索
                </button>
              </div>
            </div>
            <div className="flex gap-6 items-center">
              <Link to="/cart" className="flex flex-col items-center cursor-pointer hover:opacity-70">
                <i className="ri-shopping-cart-line text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-1">カート</span>
              </Link>
              <div className="flex flex-col items-center cursor-pointer hover:opacity-70">
                <i className="ri-heart-line text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-1">お気に入り</span>
              </div>
              <div className="flex flex-col items-center cursor-pointer hover:opacity-70">
                <i className="ri-history-line text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-1">履歴</span>
              </div>
              <div className="flex flex-col items-center cursor-pointer hover:opacity-70">
                <i className="ri-store-line text-2xl text-gray-700"></i>
                <span className="text-xs text-gray-600 mt-1">業販</span>
              </div>
            </div>
          </div>
        </header>
      )}
    </>
  );
}
